/**
 * Parse CSV text into an array of rows, where each row is an array of strings.
 *
 * - Fields are separated by commas.
 * - A field wrapped in double quotes may contain commas and line breaks.
 *   Inside a quoted field, "" represents one double quote.
 * - Lines end with \n or \r\n.
 * - A final line break does not add an empty row, and empty text gives [].
 */
export function parseCsv(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseCsv expects a string');
  }

  const rows = [];
  if (text.length === 0) return rows;

  let row = [];
  let field = '';
  let i = 0;

  const endField = () => {
    row.push(field);
    field = '';
  };

  while (i < text.length) {
    const ch = text[i];

    if (ch === '"' && field === '') {
      // Quoted field: consume until the closing quote.
      i += 1;
      while (i < text.length) {
        const c = text[i];
        if (c === '"') {
          if (text[i + 1] === '"') {
            field += '"';
            i += 2;
            continue;
          }
          i += 1; // closing quote
          break;
        }
        field += c;
        i += 1;
      }
      continue;
    }

    if (ch === ',') {
      endField();
      i += 1;
      continue;
    }

    if (ch === '\n') {
      endField();
      rows.push(row);
      row = [];
      i += 1;
      continue;
    }

    if (ch === '\r' && text[i + 1] === '\n') {
      endField();
      rows.push(row);
      row = [];
      i += 2;
      continue;
    }

    field += ch;
    i += 1;
  }

  // Only add the pending row when the text does not end with a line break.
  if (field !== '' || row.length > 0) {
    endField();
    rows.push(row);
  }

  return rows;
}

/**
 * Turn parsed CSV rows into objects.
 *
 * The first row is the header; one object is returned per remaining row,
 * keyed by the header. Missing columns become empty strings.
 */
export function toObjects(rows) {
  if (!Array.isArray(rows) || rows.length === 0) return [];

  const header = rows[0];
  const objects = [];

  for (let r = 1; r < rows.length; r += 1) {
    const row = rows[r] ?? [];
    const object = {};
    for (let c = 0; c < header.length; c += 1) {
      const value = row[c];
      object[header[c]] = value === undefined || value === null ? '' : value;
    }
    objects.push(object);
  }

  return objects;
}

import test from 'node:test';
import assert from 'node:assert/strict';

import { parseCsv, toObjects } from '../src/csv.js';

test('empty text gives []', () => {
  assert.deepEqual(parseCsv(''), []);
});

test('plain comma separated rows', () => {
  assert.deepEqual(parseCsv('a,b,c\n1,2,3'), [
    ['a', 'b', 'c'],
    ['1', '2', '3'],
  ]);
});

test('a final line break does not add an empty row', () => {
  assert.deepEqual(parseCsv('a,b\n1,2\n'), [
    ['a', 'b'],
    ['1', '2'],
  ]);
});

test('CRLF line endings', () => {
  assert.deepEqual(parseCsv('a,b\r\n1,2\r\n'), [
    ['a', 'b'],
    ['1', '2'],
  ]);
});

test('quoted field may contain commas', () => {
  assert.deepEqual(parseCsv('a,"b,c",d'), [['a', 'b,c', 'd']]);
});

test('quoted field may contain line breaks', () => {
  assert.deepEqual(parseCsv('a,"line1\nline2",c'), [['a', 'line1\nline2', 'c']]);
  assert.deepEqual(parseCsv('a,"line1\r\nline2",c'), [['a', 'line1\r\nline2', 'c']]);
});

test('double quotes inside a quoted field mean one double quote', () => {
  assert.deepEqual(parseCsv('a,"say ""hi""",c'), [['a', 'say "hi"', 'c']]);
  assert.deepEqual(parseCsv('""""'), [['"']]);
});

test('empty fields are preserved', () => {
  assert.deepEqual(parseCsv('a,,c'), [['a', '', 'c']]);
  assert.deepEqual(parseCsv(','), [['', '']]);
});

test('quoted empty field is one empty string', () => {
  assert.deepEqual(parseCsv('a,"",c'), [['a', '', 'c']]);
});

test('toObjects maps header to values', () => {
  const rows = parseCsv('name,age\nAnn,30\nBob,25');
  assert.deepEqual(toObjects(rows), [
    { name: 'Ann', age: '30' },
    { name: 'Bob', age: '25' },
  ]);
});

test('toObjects fills missing columns with empty strings', () => {
  const rows = parseCsv('a,b,c\n1\n2,3');
  assert.deepEqual(toObjects(rows), [
    { a: '1', b: '', c: '' },
    { a: '2', b: '3', c: '' },
  ]);
});

test('toObjects handles header-only and empty input', () => {
  assert.deepEqual(toObjects(parseCsv('a,b')), []);
  assert.deepEqual(toObjects([]), []);
});

